export type IdeaKind = 'new' | 'merge' | 'cut' | 'distill';

/** new: an app unlike anything in the portfolio. merge: joins 2-3 existing apps into something that yields insight, knowledge, information or a new creation. cut: the intersection of two apps or two domains (what lives only where they meet). distill: boils one or more existing apps down to their essence (a rule, an index, a one-page tool). */
/** example: one concrete case the first screen must reproduce. test: how the tool's reliability is checked. */
export interface Idea { kind: IdeaKind; title: string; idea: string; yields?: string; from?: string[]; example?: string; test?: string }

export interface NewAxis { kind: 'domain' | 'action'; label: string; why: string; ideas: { title: string; idea: string; example?: string; test?: string }[] }

const n = (title: string, idea: string): Idea => ({ kind: 'new', title, idea });
const m = (title: string, idea: string, yields: string, from: string[]): Idea => ({ kind: 'merge', title, idea, yields, from });
const c = (title: string, idea: string, yields: string, from: string[]): Idea => ({ kind: 'cut', title, idea, yields, from });
const d = (title: string, idea: string, yields: string, from: string[]): Idea => ({ kind: 'distill', title, idea, yields, from });
const x = (idea: Idea, example: string, test: string): Idea => ({ ...idea, example, test });

